    int64_t arg_layer_index; JS_ToInt64(ctx, &arg_layer_index, argv[1]);
    Ref<PhysicsMaterial> arg_physics_material;
    if (JS_IsNumber(argv[2])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_physics_material; JS_ToInt64(ctx, &h_physics_material, argv[2]);
        Object* obj_physics_material = qjs_ctx->get_object_registry()->get_object(h_physics_material);
        arg_physics_material = Ref<PhysicsMaterial>(Object::cast_to<PhysicsMaterial>(obj_physics_material));
    } else {
        // Object with __handle property
        JSValue jh_physics_material = JS_GetPropertyStr(ctx, argv[2], "__handle");
        if (!JS_IsUndefined(jh_physics_material)) {
            int64_t h_physics_material; JS_ToInt64(ctx, &h_physics_material, jh_physics_material);
            Object* obj_physics_material = qjs_ctx->get_object_registry()->get_object(h_physics_material);
            arg_physics_material = Ref<PhysicsMaterial>(Object::cast_to<PhysicsMaterial>(obj_physics_material));
        }
        JS_FreeValue(ctx, jh_physics_material);
    }

    typed_obj->set_physics_layer_physics_material(arg_layer_index, arg_physics_material);
