// Method: TileSet::add_pattern
static JSValue js_TileSet_add_pattern(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "TileSet.add_pattern: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "TileSet.add_pattern: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "TileSet.add_pattern: invalid or freed object");
    }

    TileSet* typed_obj = Object::cast_to<TileSet>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "TileSet.add_pattern: object is not a TileSet");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 2) {
        return JS_ThrowTypeError(ctx, "TileSet.add_pattern: expected at least 1 arguments, got %d", argc - 1);
    }

    // Convert arguments
    Ref<TileMapPattern> arg_pattern;
    if (JS_IsNumber(argv[1])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_pattern; JS_ToInt64(ctx, &h_pattern, argv[1]);
        Object* obj_pattern = qjs_ctx->get_object_registry()->get_object(h_pattern);
        arg_pattern = Ref<TileMapPattern>(Object::cast_to<TileMapPattern>(obj_pattern));
    } else {
        // Object with __handle property
        JSValue jh_pattern = JS_GetPropertyStr(ctx, argv[1], "__handle");
        if (!JS_IsUndefined(jh_pattern)) {
            int64_t h_pattern; JS_ToInt64(ctx, &h_pattern, jh_pattern);
            Object* obj_pattern = qjs_ctx->get_object_registry()->get_object(h_pattern);
            arg_pattern = Ref<TileMapPattern>(Object::cast_to<TileMapPattern>(obj_pattern));
        }
        JS_FreeValue(ctx, jh_pattern);
    }
    // Optional argument: index (default: -1)
    int64_t arg_index = -1;
    if (argc > 2) {
        // Override default with provided value
        JS_ToInt64(ctx, &arg_index, argv[2]);
    }

    int64_t result = typed_obj->add_pattern(arg_pattern, arg_index);
    return JS_NewInt64(ctx, result);
}

// Method: TileSet::get_pattern
static JSValue js_TileSet_get_pattern(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "TileSet.get_pattern: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "TileSet.get_pattern: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "TileSet.get_pattern: invalid or freed object");
    }

    TileSet* typed_obj = Object::cast_to<TileSet>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "TileSet.get_pattern: object is not a TileSet");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "TileSet.get_pattern: expected at least 0 arguments, got %d", argc - 1);
    }

    // Convert arguments
    // Optional argument: index (default: -1)
    int64_t arg_index = -1;
    if (argc > 1) {
        // Override default with provided value
        JS_ToInt64(ctx, &arg_index, argv[1]);
    }

    Ref<TileMapPattern> result = typed_obj->get_pattern(arg_index);
    if (result.is_null()) return JS_NULL;
    Object* ret_obj_ptr = result.ptr();
    int64_t ret_handle = qjs_ctx->get_object_registry()->get_or_create_handle(ret_obj_ptr);
    // Store class name in local String to avoid dangling pointer from temporary
    String ret_class_str = ret_obj_ptr->get_class();
    CharString ret_class_utf8 = ret_class_str.utf8();
    const char* ret_class_name = ret_class_utf8.get_data();
    // Use __wrap_existing_godot_object to create a proper Proxy with method/property access
    JSValue global = JS_GetGlobalObject(ctx);
    JSValue wrap_fn = JS_GetPropertyStr(ctx, global, "__wrap_existing_godot_object");
    if (JS_IsFunction(ctx, wrap_fn)) {
        JSValue args[2] = { JS_NewInt64(ctx, ret_handle), JS_NewString(ctx, ret_class_name) };
        JSValue wrapped = JS_Call(ctx, wrap_fn, JS_UNDEFINED, 2, args);
        JS_FreeValue(ctx, args[0]);
        JS_FreeValue(ctx, args[1]);
        JS_FreeValue(ctx, wrap_fn);
        JS_FreeValue(ctx, global);
        return wrapped;
    }
    JS_FreeValue(ctx, wrap_fn);
    JS_FreeValue(ctx, global);
    // Fallback: return raw object
    JSValue ret_obj = JS_NewObject(ctx);
    JS_SetPropertyStr(ctx, ret_obj, "__handle", JS_NewInt64(ctx, ret_handle));
    JS_SetPropertyStr(ctx, ret_obj, "__class", JS_NewString(ctx, ret_class_name));
    return ret_obj;
}

